import numpy as np

def calculate_E(p, q, r):
    """Calculates the expression E = p/q + r/p + 1/r + q"""
    if p == 0 or q == 0 or r == 0:
        return float('inf')
    return p/q + r/p + 1/r + q

def E_constrained(p, q):
    """Calculates E given p and q, using the constraint s=1: r = (p - q(p+1)) / (p+1 - q)"""
    # Constraint requires r > 0, so p - q(p+1) > 0 => q < p/(p+1)
    if q >= p / (p + 1) or p <= 0 or q <= 0:
        return float('inf')

    # Constraint requires p+1-q != 0, which is guaranteed if q < p/(p+1) < p+1

    # Calculate r
    try:
        numerator = p - q * (p + 1)
        denominator = p + 1 - q
        r = numerator / denominator
    except ZeroDivisionError:
        return float('inf') # Should not happen under the derived constraints

    # Check positivity of r (already handled by the q constraint, but good practice)
    if r <= 0:
        return float('inf')

    return calculate_E(p, q, r)

# Systematic Search
min_E = float('inf')
best_p = None
best_q = None

# Search p in the range [0.5, 3.0]
p_values = np.linspace(0.5, 3.0, 31) 

for p in p_values:
    # Search q in the range (0, p/(p+1))
    q_limit = p / (p + 1)
    q_values = np.linspace(0.01, q_limit, 31) 

    for q in q_values:
        E = E_constrained(p, q)

        if E < min_E:
            min_E = E
            best_p = p
            best_q = q

print(f"Minimum E found: {min_E}")
